{
  "name": "@kommander/ocpair",
  "version": "1.0.0",
  "description": "Hand tasks to another OpenCode server and get woken when they're done, like a background subagent. CLI and OpenCode plugin.",
  "license": "Apache-2.0",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/kommander/ocpair.git"
  },
  "keywords": [
    "opencode",
    "opencode-plugin",
    "agent",
    "skill",
    "subagent"
  ],
  "type": "module",
  "bin": {
    "ocpair": "dist/cli.js"
  },
  "exports": {
    ".": "./dist/plugin.js"
  },
  "files": [
    "dist",
    "SKILL.md"
  ],
  "publishConfig": {
    "access": "public"
  },
  "engines": {
    "node": ">=22"
  },
  "scripts": {
    "build": "bun build src/cli.ts src/plugin.ts --target node --outdir dist",
    "typecheck": "tsc --noEmit -p .",
    "prepack": "bun run build"
  },
  "devDependencies": {
    "@opencode/client": "^2.2.7",
    "@opencode/plugin": "^2.2.7",
    "@types/node": "^22",
    "typescript": "^5"
  }
}
